@Entity @Table(name="perguntas_template_vaga") public class PerguntaTemplateVagaJpaEntity { @Id private UUID id; @Column(name="template_vaga_id",nullable=false) private UUID templateVagaId; @Column(nullable=false,columnDefinition="TEXT") private String enunciado; @Enumerated(EnumType.STRING) @Column(name="tipo_resposta",nullable=false) private TipoResposta tipoResposta; @Column(nullable=false) private boolean obrigatoria; @Column(nullable=false) private int ordem; @Column(name="criado_em",nullable=false) private OffsetDateTime criadoEm; @Column(name="atualizado_em",nullable=false) private OffsetDateTime atualizadoEm; @Column(name="excluido_em") private OffsetDateTime excluidoEm; protected PerguntaTemplateVagaJpaEntity(){} PerguntaTemplateVagaJpaEntity(UUID i,UUID t,String e,TipoResposta tr,boolean o,int or,OffsetDateTime c,OffsetDateTime a,OffsetDateTime x){id=i;templateVagaId=t;enunciado=e;tipoResposta=tr;obrigatoria=o;ordem=or;criadoEm=c;atualizadoEm=a;excluidoEm=x;} @PrePersist void incluir(){OffsetDateTime n=OffsetDateTime.now();if(criadoEm==null)criadoEm=n;atualizadoEm=n;} @PreUpdate void atualizar(){atualizadoEm=OffsetDateTime.now();} UUID getId(){return id;} UUID getTemplateVagaId(){return templateVagaId;} String getEnunciado(){return enunciado;} TipoResposta getTipoResposta(){return tipoResposta;} boolean isObrigatoria(){return obrigatoria;} int getOrdem(){return ordem;} OffsetDateTime getCriadoEm(){return criadoEm;} OffsetDateTime getAtualizadoEm(){return atualizadoEm;} OffsetDateTime getExcluidoEm(){return excluidoEm;} }
